sql_local_concat.source:
public class R { public void M(DbCommand command, string userId) {
  var query = "SELECT * FROM U WHERE id = '" + userId + "'";
  command.CommandText = query;
  command.ExecuteReader(); } }

sql_stringbuilder.source:
public class R { public void M(DbCommand c, string name) {
  var sb = new StringBuilder("SELECT * FROM U WHERE n = '"); sb.Append(name).Append("'");
  c.CommandText = sb.ToString(); c.ExecuteNonQuery(); } }

sql_concat_join.source:
public class R { public void M(DbCommand c, string[] ids) {
  var list = new List<string>(); foreach (var id in ids) { list.Add(id); }
  c.CommandText = "SELECT * FROM U WHERE id IN (" + string.Join(",", list) + ")"; c.ExecuteNonQuery(); } }

sql_local_function.source:
public class R { public void M(DbCommand c, string name) {
  Run("SELECT * FROM U WHERE n = '" + name + "'");
  void Run(string sql) { c.CommandText = sql; c.ExecuteNonQuery(); } } }

sql_parameterized.source:
public class R { public void M(DbCommand c, string name) {
  c.CommandText = "SELECT * FROM U WHERE n = @n"; var prm = c.CreateParameter(); prm.ParameterName = "@n"; prm.Value = name;
  c.Parameters.Add(prm); c.ExecuteNonQuery(); } }

sql_allowlist_column.source:
public class R { static readonly HashSet<string> Cols = new() { "name", "age" };
  public void M(DbCommand c, string col) { if (!Cols.Contains(col)) { throw new ArgumentException(nameof(col)); }
    c.CommandText = "SELECT * FROM U ORDER BY " + col; c.ExecuteNonQuery(); } }

zip_entry_guarded.source:
public class R { public void M(ZipArchive archive) { foreach (var entry in archive.Entries) {
  var target = Path.GetFullPath(Path.Combine("/out", entry.FullName));
  if (!target.StartsWith("/out/", StringComparison.Ordinal)) { continue; } entry.ExtractToFile(target); } } }

