public class FromQueryAttribute : Attribute { }
public class ControllerBase { }
public class UsersController : ControllerBase { internal void Find(DbCommand c, [FromQuery] string name) { c.CommandText = "SELECT " + name; c.ExecuteNonQuery(); } }
